INSERT IGNORE INTO country_scores(country_id,talent_availability,talent_affordability,digital_infrastructure,innovation,compliance_score) SELECT id,CASE code WHEN 'IN' THEN 88 WHEN 'DE' THEN 78 WHEN 'AU' THEN 82 WHEN 'SG' THEN 91 WHEN 'US' THEN 94 WHEN 'GB' THEN 90 WHEN 'CA' THEN 86 WHEN 'PL' THEN 80 ELSE 70 END,CASE code WHEN 'IN' THEN 92 WHEN 'PL' THEN 85 WHEN 'VN' THEN 88 WHEN 'PH' THEN 86 ELSE 65 END,CASE code WHEN 'SG' THEN 98 WHEN 'US' THEN 97 WHEN 'DE' THEN 94 WHEN 'GB' THEN 96 ELSE 78 END,CASE code WHEN 'US' THEN 98 WHEN 'DE' THEN 95 WHEN 'SG' THEN 97 WHEN 'GB' THEN 94 ELSE 72 END,CASE code WHEN 'DE' THEN 80 WHEN 'NL' THEN 82 WHEN 'FI' THEN 85 WHEN 'SG' THEN 88 ELSE 68 END FROM countries;